#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
    int r1, c1, r2, c2;
    if (scanf("%d %d", &r1, &c1) != 2) return 0;
    if (scanf("%d %d", &r2, &c2) != 2) return 0;

    if (c1 != r2) {
        return 0;
    }

    int **m1 = malloc(r1 * sizeof(int *));
    for (int i = 0; i < r1; i++) {
        m1[i] = malloc(c1 * sizeof(int));
        for (int j = 0; j < c1; j++) {
            scanf("%d", &m1[i][j]);
        }
    }

    int **m2 = malloc(r2 * sizeof(int *));
    for (int i = 0; i < r2; i++) {
        m2[i] = malloc(c2 * sizeof(int));
        for (int j = 0; j < c2; j++) {
            scanf("%d", &m2[i][j]);
        }
    }

    int **res = malloc(r1 * sizeof(int *));
    for (int i = 0; i < r1; i++) {
        res[i] = calloc(c2, sizeof(int));
        for (int k = 0; k < c1; k++) {
            for (int j = 0; j < c2; j++) {
                res[i][j] += m1[i][k] * m2[k][j];
            }
        }
    }

    for (int i = 0; i < r1; i++) {
        for (int j = 0; j < c2; j++) {
            printf("%d%c", res[i][j], j == c2 - 1 ? '\n' : ' ');
        }
    }

    for (int i = 0; i < r1; i++) free(m1[i]);
    free(m1);
    for (int i = 0; i < r2; i++) free(m2[i]);
    free(m2);
    for (int i = 0; i < r1; i++) free(res[i]);
    free(res);

    return 0;
}
